import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const s="/images/logic-studio/user-guide/javascript-en.png",g=JSON.parse('{"title":"JavaScript","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/logic-studio/user-guide/javascript.md","filePath":"en/projects/logic-studio/user-guide/javascript.md","lastUpdated":1795870063000}'),i={name:"en/projects/logic-studio/user-guide/javascript.md"};function n(l,e,d,c,p,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="javascript" tabindex="-1">JavaScript <a class="header-anchor" href="#javascript" aria-label="Permalink to &quot;JavaScript&quot;">​</a></h1><p>Since <strong>0.1.136</strong>, HA write APIs return promises. For ordered execution, use <code>await ha.setSensorState(&quot;sensor.example&quot;, 1.5);</code> and then read with <code>ha.readState(&quot;sensor.example&quot;)</code>. The sensor API waits for HA confirmation and makes the confirmed value available in the readable snapshot. <code>await ha.callAction(...)</code> waits for request acceptance, not a physical device movement. Timers and explicit callback blocks remain separate continuations. 99 local tests passed; Additionally live-tested on 28 November 2026 after a full backup on HA 2026.11.3 (.193, port 80): Blocks JS state/attribute branches, writing before debug, decimal input without Enter, the previous-code warning and log clearing. Test values restored, projects and permissions preserved; examples stopped. <a href="./../#zustandstrigger-reihenfolge">Live test evidence</a>.</p><h2 id="first-example" tabindex="-1">First example <a class="header-anchor" href="#first-example" aria-label="Permalink to &quot;First example&quot;">​</a></h2><p>This example writes a message to the log with one line of code.</p><ol><li>Choose <strong>New project → JavaScript</strong> and replace the sample code with <code>ha.log(&#39;Studio-Test&#39;);</code>.</li><li>Click the test run button at the top right. You can try the code before saving it.</li><li>Look for <code>Studio-Test</code> in the <code>message</code> field in the <strong>Log</strong>. Click <strong>Save</strong> to keep the draft.</li></ol><p><a href="/images/logic-studio/user-guide/javascript-en.png"><img src="'+s+'" alt="JavaScript test run showing Studio-Test in the log"></a></p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="completion-and-signatures" tabindex="-1">Completion and signatures <a class="header-anchor" href="#completion-and-signatures" aria-label="Permalink to &quot;Completion and signatures&quot;">​</a></h3><p>Start typing an API name to see suggestions and expected arguments.</p><h3 id="test-values-and-test-run" tabindex="-1">Test values and test run <a class="header-anchor" href="#test-values-and-test-run" aria-label="Permalink to &quot;Test values and test run&quot;">​</a></h3><p>Use simulated states and check the output and errors.</p><h3 id="error-lines" tabindex="-1">Error lines <a class="header-anchor" href="#error-lines" aria-label="Permalink to &quot;Error lines&quot;">​</a></h3><p>Go to the reported line in the original source and inspect the expression.</p><h3 id="global-functions" tabindex="-1">Global functions <a class="header-anchor" href="#global-functions" aria-label="Permalink to &quot;Global functions&quot;">​</a></h3><p>Export functions from a global script and select that script in the project that uses them.</p><h3 id="play-and-autostart" tabindex="-1">Play and autostart <a class="header-anchor" href="#play-and-autostart" aria-label="Permalink to &quot;Play and autostart&quot;">​</a></h3><p>Save and start with Play. Enable autostart per project if it should start after an app restart.</p><h3 id="runtime-log" tabindex="-1">Runtime log <a class="header-anchor" href="#runtime-log" aria-label="Permalink to &quot;Runtime log&quot;">​</a></h3><p>Read log entries after an app restart. Retention is limited by age and size.</p><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><p>If HA rejects an action, check the app&#39;s approved entities and actions.</p>',21)])])}const m=a(i,[["render",n]]);export{g as __pageData,m as default};
